import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import api from "../api"; 

const ROLES = [
  {id:"student", label:"Student",  emoji:"🎓", placeholder:"your-email@example.com"},
  {id:"company", label:"Company",  emoji:"🏢", placeholder:"hr@company.com"},
  {id:"admin",   label:"Admin",    emoji:"🏛️", placeholder:"admin@stag.io"},
];

export default function Login() {
  const [role, setRole]         = useState("student");
  const [email, setEmail]       = useState("");
  const [password, setPassword] = useState("");
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading]   = useState(false);
  
  const navigate = useNavigate();
  const cfg = ROLES.find(r => r.id === role);

  const handleLogin = async () => {
    if (!email || !password) {
      alert("Please fill in your credentials");
      return;
    }

    setLoading(true);
    try {
      // إرسال طلب تسجيل الدخول لـ Django
      // نرسل 'email' ليتوافق مع الـ Serializer الجديد
      const response = await api.post('login/', {
        email: email,
        password: password
      });

      // حفظ بيانات الجلسة في المتصفح
      localStorage.setItem('token', response.data.access);
      localStorage.setItem('userRole', response.data.role);

      // التوجيه بناءً على الدور القادم من قاعدة البيانات (وليس الاختيار الصوري)
      const finalRole = response.data.role.toLowerCase();
      
      if (finalRole === "student") navigate("/student/dashboard");
      else if (finalRole === "company") navigate("/company/dashboard");
      else if (finalRole === "admin") navigate("/admin/dashboard");

    } catch (error) {
      console.error("Login error:", error);
      const errorMsg = error.response?.data?.detail || "Invalid credentials. Check your email and password.";
      alert(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex bg-[#fdf9f5]">
      {/* Left panel */}
      <div className="hidden lg:flex lg:w-[52%] bg-slate-900 flex-col relative overflow-hidden">
        <div className="absolute inset-0 dot-grid opacity-40"/>
        <div className="relative p-10">
          <Link to="/" className="font-syne font-extrabold text-2xl text-white tracking-tight">Stag<span className="text-soft">.</span>io</Link>
        </div>
        <div className="flex-1 flex flex-col justify-center px-12 pb-16 relative">
          <h1 className="font-syne font-extrabold text-white leading-tight mb-5" style={{fontSize:"clamp(2rem,3.5vw,3rem)",letterSpacing:"-1px"}}>
            Your internship journey starts <span className="text-soft">right here.</span>
          </h1>
        </div>
      </div>

      {/* Right panel */}
      <div className="flex-1 flex flex-col justify-center items-center px-6 py-12">
        <div className="w-full max-w-md">
          <h2 className="font-syne font-extrabold text-slate-900 text-3xl mb-8">Sign in</h2>

          {/* Role tabs */}
          <div className="bg-slate-100 rounded-xl p-1 flex mb-7">
            {ROLES.map(r => (
              <button key={r.id} onClick={() => setRole(r.id)}
                className={`flex-1 flex items-center justify-center gap-1.5 py-2 rounded-lg text-sm font-medium transition-all ${role===r.id?"bg-white text-slate-900 shadow-sm":"text-slate-500"}`}>
                <span>{r.emoji}</span><span>{r.label}</span>
              </button>
            ))}
          </div>

          <div className="space-y-5">
            <input 
              type="email" 
              value={email} 
              onChange={e=>setEmail(e.target.value)} 
              placeholder={cfg.placeholder} 
              className="w-full p-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" 
            />
            <div className="relative">
              <input type={showPass?"text":"password"} 
                value={password} 
                onChange={e=>setPassword(e.target.value)} 
                placeholder="••••••••" 
                className="w-full p-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
              />
              <button type="button" onClick={()=>setShowPass(!showPass)} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400">
                {showPass?"🙈":"👁️"}
              </button>
            </div>

            <button 
              onClick={handleLogin} 
              disabled={loading}
              className={`w-full bg-slate-900 text-white font-semibold py-3 rounded-xl text-sm flex justify-center items-center gap-2 ${loading ? 'opacity-70 cursor-not-allowed' : ''}`}
            >
              {loading ? "Signing in..." : "Sign in to Stag.io →"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
